fn parking_fee(hours: int) -> dec
    if hours < 1
        return 0.0
    elif hours < 5
        return 0.0 + 2.5 * (hours - 1)
    elif hours < 9
        return 0.0 + 6.0 + 1.5 * (hours - 5)
    elif hours < 14
        return 0.0 + 12.0 + 1.5 * (hours - 9)
    elif hours < 19
        return 0.0 + 18.0 + 1.5 * (hours - 14)
    elif hours < 24
        return 0.0 + 24.0 + 1.5 * (hours - 19)
    else
        return 0.0 + 24.0 + 1.5 * (hours - 24)

